<script lang="ts">import type { InventoryItem } from '$lib/api/types'; import InventoryRow from './InventoryRow.svelte'; let { items }: { items: InventoryItem[] } = $props(); let expanded = $state<string | null>(null); let grouped = $derived(Object.values(items.reduce<Record<string,{part_num:string;part_name:string;total:number;colors:InventoryItem[]}>>((all,item)=>{const row=all[item.part_num]??={part_num:item.part_num,part_name:item.part_name,total:0,colors:[]};row.total+=item.quantity;row.colors.push(item);return all;},{})));</script>
<section class="ledger" aria-label="Inventory Ledger"><header><span>Part</span><span>Total</span><span>Colors</span><span>Source sets</span></header>{#each grouped as part}<InventoryRow {part} expanded={expanded === part.part_num} onToggle={() => expanded = expanded === part.part_num ? null : part.part_num} />{/each}{#if !grouped.length}<p>No inventory pieces match this view.</p>{/if}</section>
